/**
 * Generates database/fitadapt_mysql.sql (schema + seed) from the app's catalog.
 * Run: bun scripts/build_mysql_seed.ts
 */
import { writeFileSync, mkdirSync } from "node:fs";

import { CRITERIA, EQUIPMENT_LABELS, EXERCISES } from "../src/lib/fitadapt/catalog";

const q = (v: string | number | boolean | null | undefined) =>
  v === null || v === undefined ? "NULL" : typeof v === "number" ? String(v) : typeof v === "boolean" ? (v ? "1" : "0") : `'${v.replace(/'/g, "''")}'`;

const lines: string[] = [];
lines.push(`-- FitAdapt exercise database and TOPSIS criteria (MySQL 8+)
-- Generated by scripts/build_mysql_seed.ts — do not edit by hand.

CREATE DATABASE IF NOT EXISTS fitadapt CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE fitadapt;

DROP TABLE IF EXISTS exercise_goal_scores, exercise_environments, exercise_equipment, exercise_secondary_muscles, exercises, equipment, criteria;

CREATE TABLE criteria (
  code        VARCHAR(4)   NOT NULL PRIMARY KEY,
  name        VARCHAR(64)  NOT NULL,
  description VARCHAR(255) NOT NULL,
  weight      DECIMAL(5,4) NOT NULL,
  sort_order  TINYINT      NOT NULL
) ENGINE=InnoDB;

CREATE TABLE equipment (
  id    VARCHAR(32) NOT NULL PRIMARY KEY,
  label VARCHAR(64) NOT NULL
) ENGINE=InnoDB;

CREATE TABLE exercises (
  id          VARCHAR(48)  NOT NULL PRIMARY KEY,
  name        VARCHAR(80)  NOT NULL,
  muscle      ENUM('core','chest','back','shoulders','arms','legs','glutes','cardio') NOT NULL,
  difficulty  TINYINT      NOT NULL CHECK (difficulty BETWEEN 1 AND 5),
  kind        ENUM('reps','hold') NOT NULL,
  low_impact  BOOLEAN      NOT NULL DEFAULT 0,
  instruction VARCHAR(255) NOT NULL,
  pose_label  ENUM('jumping_jacks','pull_ups','push_ups','russian_twists','squats') NULL,
  sort_order  SMALLINT     NOT NULL
) ENGINE=InnoDB;

CREATE TABLE exercise_secondary_muscles (
  exercise_id VARCHAR(48) NOT NULL,
  muscle      ENUM('core','chest','back','shoulders','arms','legs','glutes','cardio') NOT NULL,
  PRIMARY KEY (exercise_id, muscle),
  FOREIGN KEY (exercise_id) REFERENCES exercises(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE exercise_equipment (
  exercise_id  VARCHAR(48) NOT NULL,
  equipment_id VARCHAR(32) NOT NULL,
  required     BOOLEAN     NOT NULL DEFAULT 0,
  PRIMARY KEY (exercise_id, equipment_id),
  FOREIGN KEY (exercise_id) REFERENCES exercises(id) ON DELETE CASCADE,
  FOREIGN KEY (equipment_id) REFERENCES equipment(id)
) ENGINE=InnoDB;

CREATE TABLE exercise_environments (
  exercise_id VARCHAR(48) NOT NULL,
  environment ENUM('home','gym','outdoors') NOT NULL,
  PRIMARY KEY (exercise_id, environment),
  FOREIGN KEY (exercise_id) REFERENCES exercises(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE exercise_goal_scores (
  exercise_id VARCHAR(48) NOT NULL,
  goal        ENUM('lose_weight','gain_muscle','build_abs','target_part','body_build') NOT NULL,
  score       TINYINT     NOT NULL CHECK (score BETWEEN 1 AND 5),
  PRIMARY KEY (exercise_id, goal),
  FOREIGN KEY (exercise_id) REFERENCES exercises(id) ON DELETE CASCADE
) ENGINE=InnoDB;
`);

lines.push("INSERT INTO criteria (code, name, description, weight, sort_order) VALUES");
lines.push(CRITERIA.map((c, i) => `  (${q(c.code)}, ${q(c.name)}, ${q(c.description)}, ${c.weight}, ${i + 1})`).join(",\n") + ";\n");

lines.push("INSERT INTO equipment (id, label) VALUES");
lines.push(Object.entries(EQUIPMENT_LABELS).map(([id, label]) => `  (${q(id)}, ${q(label)})`).join(",\n") + ";\n");

lines.push("INSERT INTO exercises (id, name, muscle, difficulty, kind, low_impact, instruction, pose_label, sort_order) VALUES");
lines.push(
  EXERCISES.map(
    (e, i) =>
      `  (${q(e.id)}, ${q(e.name)}, ${q(e.muscle)}, ${e.difficulty}, ${q(e.kind)}, ${q(e.lowImpact)}, ${q(e.instruction)}, ${q(e.pose ?? null)}, ${i + 1})`,
  ).join(",\n") + ";\n",
);

const sec = EXERCISES.flatMap((e) => e.secondary.map((m) => `  (${q(e.id)}, ${q(m)})`));
lines.push("INSERT INTO exercise_secondary_muscles (exercise_id, muscle) VALUES");
lines.push(sec.join(",\n") + ";\n");

const eq = EXERCISES.flatMap((e) =>
  Array.from(new Set([...e.worksWith, ...e.requires])).map(
    (w) => `  (${q(e.id)}, ${q(w)}, ${q(e.requires.includes(w))})`,
  ),
);
lines.push("INSERT INTO exercise_equipment (exercise_id, equipment_id, required) VALUES");
lines.push(eq.join(",\n") + ";\n");

const env = EXERCISES.flatMap((e) => e.environments.map((v) => `  (${q(e.id)}, ${q(v)})`));
lines.push("INSERT INTO exercise_environments (exercise_id, environment) VALUES");
lines.push(env.join(",\n") + ";\n");

const goals = EXERCISES.flatMap((e) => Object.entries(e.goals).map(([g, s]) => `  (${q(e.id)}, ${q(g)}, ${s})`));
lines.push("INSERT INTO exercise_goal_scores (exercise_id, goal, score) VALUES");
lines.push(goals.join(",\n") + ";\n");

mkdirSync("database", { recursive: true });
writeFileSync("database/fitadapt_mysql.sql", lines.join("\n"));
console.log(`Wrote database/fitadapt_mysql.sql (${EXERCISES.length} exercises, ${CRITERIA.length} criteria)`);
